import{S as o,o as t,c as d,Q as c}from"./chunks/framework.C28VfJ6E.js";const m=JSON.parse('{"title":"介绍","description":"","frontmatter":{},"headers":[],"relativePath":"guide/introduction.md","filePath":"guide/introduction.md"}'),r={name:"guide/introduction.md"};function a(i,e,n,s,l,h){return t(),d("div",null,[...e[0]||(e[0]=[c('<h1 id="介绍" tabindex="-1">介绍 <a class="header-anchor" href="#介绍" aria-label="Permalink to &quot;介绍&quot;">​</a></h1><p><strong>KK UI</strong> 是一套基于 Vue 3 的组件库，视觉语言为「柔光几何」（Soft Geometry）： 用克制的圆角、柔和的阴影和一致的动效节奏，让界面看起来是会呼吸的。</p><h2 id="核心特性" tabindex="-1">核心特性 <a class="header-anchor" href="#核心特性" aria-label="Permalink to &quot;核心特性&quot;">​</a></h2><ul><li><strong>三层设计 Token</strong>：Primitive（原始值）→ Semantic（语义）→ Component（组件级），组件只消费语义层，主题切换只需覆盖语义层。</li><li><strong>4 套内置主题</strong>：<code>light</code> / <code>dark</code> / <code>soft</code> / <code>cyber</code>，通过 <code>&lt;html data-kk-theme&gt;</code> 切换，纯 CSS 变量驱动，无运行时开销。</li><li><strong>组件配套完整</strong>：每个组件目录都包含 <code>Xxx.vue</code>、<code>types.ts</code>、<code>style.scss</code>、<code>__tests__</code>、<code>README.md</code>、<code>index.ts</code>。</li><li><strong>零样式泄漏</strong>：不使用 <code>&lt;style scoped&gt;</code> 与全局标签选择器，样式统一走 BEM + <code>.scss</code>。</li></ul><h2 id="组件总览" tabindex="-1">组件总览 <a class="header-anchor" href="#组件总览" aria-label="Permalink to &quot;组件总览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>分类</th><th>组件</th></tr></thead><tbody><tr><td>通用</td><td><code>KkButton</code>、<code>KkIcon</code></td></tr><tr><td>布局</td><td><code>KkSpace</code>、<code>KkDivider</code>、<code>KkCard</code></td></tr><tr><td>数据展示</td><td><code>KkTag</code></td></tr><tr><td>数据录入</td><td><code>KkInput</code>、<code>KkForm</code>、<code>KkFormItem</code></td></tr></tbody></table><h2 id="设计理念" tabindex="-1">设计理念 <a class="header-anchor" href="#设计理念" aria-label="Permalink to &quot;设计理念&quot;">​</a></h2><ol><li><strong>Token 即契约</strong>：任何颜色、圆角、间距、阴影、时长都必须来自 token，禁止硬编码。</li><li><strong>语义优先</strong>：组件面向「主色 / 成功 / 警告 / 危险」这样的语义，而不是具体色值。</li><li><strong>可呼吸的动效</strong>：统一使用 <code>--kk-duration-*</code> 与 <code>--kk-ease-out</code>，并在 <code>prefers-reduced-motion</code> 下自动收敛。</li></ol><h2 id="浏览器支持" tabindex="-1">浏览器支持 <a class="header-anchor" href="#浏览器支持" aria-label="Permalink to &quot;浏览器支持&quot;">​</a></h2><p>现代浏览器（Chrome / Edge / Firefox / Safari 最新两个大版本），依赖 CSS 变量、<code>:has()</code> 与 <code>color-mix()</code>。</p>',10)])])}const k=o(r,[["render",a]]);export{m as __pageData,k as default};
